{
  "name": "@headsdown/opencode",
  "version": "0.1.3",
  "description": "HeadsDown availability and focus-mode gating plugin for OpenCode.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "headsdown",
    "availability",
    "focus"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/headsdownapp/headsdown-opencode.git"
  },
  "homepage": "https://github.com/headsdownapp/headsdown-opencode#readme",
  "bugs": {
    "url": "https://github.com/headsdownapp/headsdown-opencode/issues"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "dev": "tsc -p tsconfig.build.json --watch",
    "test": "vitest run"
  },
  "dependencies": {
    "@headsdown/sdk": "^0.2.14",
    "@opencode-ai/plugin": "^1.14.25"
  },
  "devDependencies": {
    "@types/node": "^25.6.0",
    "typescript": "^6.0.3",
    "vitest": "^4.1.5"
  },
  "overrides": {
    "uuid": "^14.0.0"
  }
}
